import React, { useState, useEffect } from 'react';
import {
    Grid,
    Paper,
    Typography,
    Box,
    Card,
    CardContent,
    Button,
    CircularProgress,
    Alert,
    Chip,
    Divider,
    LinearProgress
} from '@mui/material';
import {
    CheckCircleOutline,
    AccessTime,
    EventNote,
    TrendingUp,
    Schedule
} from '@mui/icons-material';
import { attendanceService, dashboardService } from '../../services/api';
import { useAuth } from '../../context/AuthContext';

const EmployeeDashboard = () => {
    const { user } = useAuth();
    const [dashboardData, setDashboardData] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [checkingIn, setCheckingIn] = useState(false);
    const [checkingOut, setCheckingOut] = useState(false);
    const [todayStatus, setTodayStatus] = useState(null);

    useEffect(() => {
        fetchDashboardData();
    }, []);

    const fetchDashboardData = async () => {
        try {
            setLoading(true);
            const [dashboardRes, statusRes] = await Promise.all([
                dashboardService.getEmployeeDashboard(),
                attendanceService.getStatus()
            ]);
            setDashboardData(dashboardRes.data.data);
            setTodayStatus(statusRes.data.status);
            setError('');
        } catch (err) {
            setError('Failed to load dashboard data');
        } finally {
            setLoading(false);
        }
    };

    const handleCheckIn = async () => {
        try {
            setCheckingIn(true);
            await attendanceService.checkIn({
                latitude: 0,
                longitude: 0,
                deviceInfo: 'Web Browser'
            });
            await fetchDashboardData();
            alert('✅ Check-in successful!');
        } catch (err) {
            alert(err.response?.data?.message || 'Check-in failed');
        } finally {
            setCheckingIn(false);
        }
    };

    const handleCheckOut = async () => {
        try {
            setCheckingOut(true);
            await attendanceService.checkOut();
            await fetchDashboardData();
            alert('✅ Check-out successful!');
        } catch (err) {
            alert(err.response?.data?.message || 'Check-out failed');
        } finally {
            setCheckingOut(false);
        }
    };

    if (loading) {
        return (
            <Box display="flex" justifyContent="center" alignItems="center" minHeight="60vh">
                <CircularProgress />
            </Box>
        );
    }

    if (error) {
        return (
            <Alert severity="error" sx={{ mt: 2 }}>
                {error}
            </Alert>
        );
    }

    const { monthlyStats, leaveBalance, weeklyAttendance } = dashboardData || {};
    const today = todayStatus || {};

    const getStatusColor = (status) => {
        switch(status) {
            case 'present': return 'success';
            case 'late': return 'warning';
            case 'absent': return 'error';
            default: return 'default';
        }
    };

    return (
        <Box>
            <Paper sx={{ p: 3, mb: 3, bgcolor: 'primary.main', color: 'white' }}>
                <Typography variant="h4" gutterBottom>
                    Welcome back, {user?.name}! 👋
                </Typography>
                <Typography variant="subtitle1">
                    {user?.position} at {user?.department} Department
                </Typography>
                <Typography variant="body2" sx={{ mt: 1, opacity: 0.8 }}>
                    Employee ID: {user?.employeeId}
                </Typography>
            </Paper>

            <Paper sx={{ p: 3, mb: 3 }}>
                <Grid container spacing={2}>
                    <Grid item xs={12} sm={6}>
                        <Button
                            fullWidth
                            variant="contained"
                            color="success"
                            onClick={handleCheckIn}
                            disabled={today?.isCheckedIn || checkingIn}
                            sx={{ py: 2 }}
                            startIcon={<CheckCircleOutline />}
                        >
                            {checkingIn ? 'Checking in...' : today?.isCheckedIn ? 'Already Checked In ✅' : 'Check In'}
                        </Button>
                    </Grid>
                    <Grid item xs={12} sm={6}>
                        <Button
                            fullWidth
                            variant="contained"
                            color="error"
                            onClick={handleCheckOut}
                            disabled={!today?.isCheckedIn || today?.isCheckedOut || checkingOut}
                            sx={{ py: 2 }}
                            startIcon={<Schedule />}
                        >
                            {checkingOut ? 'Checking out...' : today?.isCheckedOut ? 'Checked Out ✅' : 'Check Out'}
                        </Button>
                    </Grid>
                </Grid>
                {today?.isCheckedIn && (
                    <Box sx={{ mt: 2 }}>
                        <Typography variant="body2" color="textSecondary">
                            Checked in at: {new Date(today.checkInTime).toLocaleTimeString()}
                            {today?.isCheckedOut && ` | Checked out at: ${new Date(today.checkOutTime).toLocaleTimeString()}`}
                            {today?.workingHours > 0 && ` | Hours: ${today.workingHours}h`}
                        </Typography>
                        <Chip 
                            label={today.status?.toUpperCase() || 'PRESENT'} 
                            color={getStatusColor(today.status)}
                            size="small"
                            sx={{ mt: 1 }}
                        />
                    </Box>
                )}
            </Paper>

            <Grid container spacing={3} sx={{ mb: 3 }}>
                <Grid item xs={12} sm={6} md={3}>
                    <Card>
                        <CardContent>
                            <Box display="flex" alignItems="center" justifyContent="space-between">
                                <Typography color="textSecondary" gutterBottom>
                                    Today's Status
                                </Typography>
                                <CheckCircleOutline color={today?.isCheckedIn ? 'success' : 'disabled'} />
                            </Box>
                            <Typography variant="h5">
                                {today?.isCheckedIn ? (today?.isCheckedOut ? 'Completed' : 'Active') : 'Not Started'}
                            </Typography>
                        </CardContent>
                    </Card>
                </Grid>

                <Grid item xs={12} sm={6} md={3}>
                    <Card>
                        <CardContent>
                            <Box display="flex" alignItems="center" justifyContent="space-between">
                                <Typography color="textSecondary" gutterBottom>
                                    This Month
                                </Typography>
                                <AccessTime color="primary" />
                            </Box>
                            <Typography variant="h5">
                                {monthlyStats?.totalDays || 0} days
                            </Typography>
                            <Typography variant="body2" color="textSecondary">
                                {monthlyStats?.totalHours || 0} hours
                            </Typography>
                        </CardContent>
                    </Card>
                </Grid>

                <Grid item xs={12} sm={6} md={3}>
                    <Card>
                        <CardContent>
                            <Box display="flex" alignItems="center" justifyContent="space-between">
                                <Typography color="textSecondary" gutterBottom>
                                    Leave Balance
                                </Typography>
                                <EventNote color="warning" />
                            </Box>
                            <Typography variant="h5">
                                {leaveBalance?.available || 0}
                            </Typography>
                            <Typography variant="body2" color="textSecondary">
                                Used: {leaveBalance?.used || 0} / Total: {leaveBalance?.total || 0}
                            </Typography>
                            <LinearProgress 
                                variant="determinate" 
                                value={(leaveBalance?.used / leaveBalance?.total) * 100 || 0}
                                sx={{ mt: 1 }}
                            />
                        </CardContent>
                    </Card>
                </Grid>

                <Grid item xs={12} sm={6} md={3}>
                    <Card>
                        <CardContent>
                            <Box display="flex" alignItems="center" justifyContent="space-between">
                                <Typography color="textSecondary" gutterBottom>
                                    Overtime
                                </Typography>
                                <TrendingUp color="info" />
                            </Box>
                            <Typography variant="h5">
                                {monthlyStats?.totalOvertime || 0}h
                            </Typography>
                            <Typography variant="body2" color="textSecondary">
                                This month
                            </Typography>
                        </CardContent>
                    </Card>
                </Grid>
            </Grid>

            {weeklyAttendance && weeklyAttendance.length > 0 && (
                <Paper sx={{ p: 3, mb: 3 }}>
                    <Typography variant="h6" gutterBottom>
                        📊 Weekly Attendance
                    </Typography>
                    <Divider sx={{ mb: 2 }} />
                    <Grid container spacing={2}>
                        {weeklyAttendance.map((day, index) => (
                            <Grid item xs key={index}>
                                <Box textAlign="center">
                                    <Typography variant="caption" display="block">
                                        {new Date(day.date).toLocaleDateString('en-US', { weekday: 'short' })}
                                    </Typography>
                                    <Chip 
                                        label={day.status?.toUpperCase() || 'ABSENT'}
                                        color={getStatusColor(day.status)}
                                        size="small"
                                        sx={{ mt: 1 }}
                                    />
                                    {day.workingHours > 0 && (
                                        <Typography variant="caption" display="block" sx={{ mt: 0.5 }}>
                                            {day.workingHours}h
                                        </Typography>
                                    )}
                                </Box>
                            </Grid>
                        ))}
                    </Grid>
                </Paper>
            )}
        </Box>
    );
};

export default EmployeeDashboard;
